const enc = new TextEncoder();
const http = "GET /health HTTP/1.1\r\nHost: 10.0.3.25:8080\r\n\r\n";

const TCP_HEADER = 20;  // minimum, no options
const IPV4_HEADER = 20; // minimum, no options
const ETH_HEADER = 14;  // destination MAC 6 + source MAC 6 + type 2

const app = enc.encode(http).length;
const segment = app + TCP_HEADER;
const packet = segment + IPV4_HEADER;
const frame = packet + ETH_HEADER;

console.log(`HTTP request: ${app} bytes`);
console.log(`TCP segment: ${segment} bytes`);
console.log(`IPv4 packet: ${packet} bytes`);
console.log(`Ethernet frame: ${frame} bytes`);
